/// Current language code.
let currentLang = "en";

/// Get translated string by key. Supports {placeholder} substitution.
function t(key, params) {
  const lang = I18N_STRINGS[currentLang] || I18N_STRINGS.en;
  let str = lang[key] || I18N_STRINGS.en[key] || key;
  if (params) {
    for (const [k, v] of Object.entries(params)) {
      str = str.replace(new RegExp("\\{" + k + "\\}", "g"), String(v));
    }
  }
  return str;
}

/// Apply translations to all elements with data-i18n or data-i18n-title attributes.
function applyI18n() {
  document.documentElement.lang = currentLang;
  // RTL for Arabic.
  document.documentElement.dir = (currentLang === "ar") ? "rtl" : "ltr";
  // Text content.
  document.querySelectorAll("[data-i18n]").forEach(el => {
    const key = el.getAttribute("data-i18n");
    el.textContent = t(key);
  });
  // Title attributes.
  document.querySelectorAll("[data-i18n-title]").forEach(el => {
    const key = el.getAttribute("data-i18n-title");
    el.title = t(key);
  });
  // Placeholder attributes.
  document.querySelectorAll("[data-i18n-placeholder]").forEach(el => {
    const key = el.getAttribute("data-i18n-placeholder");
    el.placeholder = t(key);
  });
  // Option elements.
  document.querySelectorAll("[data-i18n-option]").forEach(el => {
    const key = el.getAttribute("data-i18n-option");
    el.textContent = t(key);
  });
}

/// Set language and apply.
function setLanguage(lang) {
  currentLang = lang;
  try { localStorage.setItem("womd_lang", lang); } catch {}
  applyI18n();
}
